        "officialSolutionKm": "ក. ចំនួនករណីអាច៖\n$n(S) = C(10, 3) = \\frac{10!}{3!7!} = \\frac{10\\times 9\\times 8}{3\\times 2\\times 1} = 120$ ករណី។\n\nខ. ប្រូបាបព្រឹត្តិការណ៍ $A$៖ «ចាប់បានបាល់សទាំង ៣»៖\n- ចំនួនករណីស្រប៖ $n(A) = C(4, 3) = 4$\n- ប្រូបាប៖ $P(A) = \\frac{n(A)}{n(S)} = \\frac{4}{120} = \\frac{1}{30}$។\n\nគ. ប្រូបាបព្រឹត្តិការណ៍ $B$៖ «ចាប់បានបាល់សយ៉ាងតិច ១»៖\nព្រឹត្តិការណ៍ផ្ទុយ $\\bar{B}$ គឺ «ចាប់បានបាល់ខ្មៅទាំង ៣ (គ្មានបាល់ស)»៖\n- $n(\\bar{B}) = C(6, 3) = \\frac{6\\times 5\\times 4}{6} = 20$\n- $P(\\bar{B}) = \\frac{20}{120} = \\frac{1}{6}$\n- ដូចនេះ $P(B) = 1 - P(\\bar{B}) = 1 - \\frac{1}{6} = \\frac{5}{6}$។",
