        "problemTextKm": "គណនាលីមីតខាងក្រោម៖\n\nក. $A = \\lim_{x\\to +\\infty} (3x^2 - x)$\n\nខ. $B = \\lim_{x\\to 2} \\frac{\\sqrt{x+2}-2}{4-x^2}$\n\nគ. $C = \\lim_{x\\to +\\infty} \\frac{e^x - x^2 + x}{x}$",
        "problemTextEn": "Evaluate limits:\na. $A = \\lim_{x\\to +\\infty} (3x^2 - x)$\nb. $B = \\lim_{x\\to 2} \\frac{\\sqrt{x+2}-2}{4-x^2}$\nc. $C = \\lim_{x\\to +\\infty} \\frac{e^x - x^2 + x}{x}$",
        "officialSolutionKm": "ក. $A = \\lim_{x\\to +\\infty} x^2\\left(3 - \\frac{1}{x}\\right) = +\\infty(3 - 0) = +\\infty$\n\nខ. រាង $\\frac{0}{0}$៖ គុណកន្សោមឆ្លាស់ $\\sqrt{x+2}+2$៖\n$B = \\lim_{x\\to 2} \\frac{(x+2)-4}{(2-x)(2+x)(\\sqrt{x+2}+2)} = \\lim_{x\\to 2} \\frac{-(2-x)}{(2-x)(2+x)(\\sqrt{x+2}+2)} = \\lim_{x\\to 2} \\frac{-1}{(2+x)(\\sqrt{x+2}+2)} = \\frac{-1}{4(2+2)} = -\\frac{1}{16}$\n\nគ. $C = \\lim_{x\\to +\\infty} \\left(\\frac{e^x}{x} - x + 1\\right) = +\\infty$ (ដោយ $\\lim_{x\\to +\\infty} \\frac{e^x}{x} = +\\infty$)។",
