        "problemTextKm": "គណនាលីមីតខាងក្រោម៖\n\nក. $A = \\lim_{x\\to 1} \\frac{x^3 - 1}{x^2 + 2x - 3}$\n\nខ. $B = \\lim_{x\\to 0} \\frac{\\sqrt{1+2x} - 1}{x}$\n\nគ. $C = \\lim_{x\\to +\\infty} \\frac{2e^x + x}{e^x - 1}$",
        "problemTextEn": "Evaluate limits:\na. $A = \\lim_{x\\to 1} \\frac{x^3 - 1}{x^2 + 2x - 3}$\nb. $B = \\lim_{x\\to 0} \\frac{\\sqrt{1+2x} - 1}{x}$\nc. $C = \\lim_{x\\to +\\infty} \\frac{2e^x + x}{e^x - 1}$",
        "officialSolutionKm": "ក. រាង $\\frac{0}{0}$៖\n$A = \\lim_{x\\to 1} \\frac{(x-1)(x^2+x+1)}{(x-1)(x+3)} = \\lim_{x\\to 1} \\frac{x^2+x+1}{x+3} = \\frac{1+1+1}{1+3} = \\frac{3}{4}$។\n\nខ. រាង $\\frac{0}{0}$៖ គុណកន្សោមឆ្លាស់ $\\sqrt{1+2x}+1$៖\n$B = \\lim_{x\\to 0} \\frac{(1+2x)-1}{x(\\sqrt{1+2x}+1)} = \\lim_{x\\to 0} \\frac{2x}{x(\\sqrt{1+2x}+1)} = \\lim_{x\\to 0} \\frac{2}{\\sqrt{1+2x}+1} = \\frac{2}{1+1} = 1$។\n\nគ. ចែកភាគយក និងភាគបែងនឹង $e^x$៖\n$C = \\lim_{x\\to +\\infty} \\frac{2 + \\frac{x}{e^x}}{1 - \\frac{1}{e^x}} = \\frac{2 + 0}{1 - 0} = 2$ (ដោយ $\\lim_{x\\to +\\infty} \\frac{x}{e^x} = 0$)។",
        "officialSolutionEn": "a. A = 3/4. b. B = 1 via conjugate. c. C = 2 dividing by e^x.",
