        "titleKm": "លំហាត់ទី ២៖ ចំនួនកុំផ្លិច (Complex Numbers)",
        "titleEn": "Problem 2: Complex Numbers",
        "problemTextKm": "គេឱ្យចំនួនកុំផ្លិច $z_1 = 1 + i$ និង $z_2 = \\sqrt{3} - i$។\n\nក. សរសេរ $z_1$ និង $z_2$ ជាទម្រង់ត្រីកោណមាត្រ។\n\nខ. គណនាផលគុណ $P = z_1 \\cdot z_2$ ជាទម្រង់ពីជគណិត និងជាទម្រង់ត្រីកោណមាត្រ។\n\nគ. ទាញរកតម្លៃពិតប្រាកដនៃ $\\cos\\frac{\\pi}{12}$ និង $\\sin\\frac{\\pi}{12}$។",
        "problemTextEn": "Given $z_1 = 1+i$ and $z_2 = \\sqrt{3}-i$.\na. Write $z_1$ and $z_2$ in trigonometric form.\nb. Compute product $P = z_1 \\cdot z_2$ in algebraic and trigonometric form.\nc. Deduce exact values of $\\cos(\\pi/12)$ and $\\sin(\\pi/12)$.",
        "officialSolutionKm": "ក. ទម្រង់ត្រីកោណមាត្រ៖\n- $z_1 = \\sqrt{2}\\left(\\cos\\frac{\\pi}{4} + i\\sin\\frac{\\pi}{4}\\right)$\n- $z_2 = 2\\left(\\cos\\left(-\\frac{\\pi}{6}\\right) + i\\sin\\left(-\\frac{\\pi}{6}\\right)\\right)$\n\nខ. ផលគុណ $P = z_1 \\cdot z_2$៖\n- ទម្រង់ពីជគណិត៖ $P = (1+i)(\\sqrt{3}-i) = (\\sqrt{3}+1) + i(\\sqrt{3}-1)$\n- ទម្រង់ត្រីកោណមាត្រ៖ $P = 2\\sqrt{2}\\left(\\cos\\left(\\frac{\\pi}{4}-\\frac{\\pi}{6}\\right) + i\\sin\\left(\\frac{\\pi}{4}-\\frac{\\pi}{6}\\right)\\right) = 2\\sqrt{2}\\left(\\cos\\frac{\\pi}{12} + i\\sin\\frac{\\pi}{12}\\right)$\n\nគ. តម្លៃពិតប្រាកដ៖\n- $\\cos\\frac{\\pi}{12} = \\frac{\\sqrt{3}+1}{2\\sqrt{2}} = \\frac{\\sqrt{6}+\\sqrt{2}}{4}$\n- $\\sin\\frac{\\pi}{12} = \\frac{\\sqrt{3}-1}{2\\sqrt{2}} = \\frac{\\sqrt{6}-\\sqrt{2}}{4}$។",
        "officialSolutionEn": "z1=√2 cis(π/4), z2=2 cis(-π/6). Product P = (√3+1)+i(√3-1) = 2√2 cis(π/12). Exact cos(π/12)=(√6+√2)/4, sin(π/12)=(√6-√2)/4.",
