        "problemTextEn": "Bag contains 9 marbles: 4 blue and 5 red. Draw 3 marbles simultaneously.\na. Find probability of drawing all same color.\nb. Find probability of drawing at least 1 red marble.",
        "officialSolutionKm": "ចំនួនករណីអាច៖ $n(S) = C(9, 3) = \\frac{9\\times 8\\times 7}{6} = 84$ ករណី។\n\nក. ព្រឹត្តិការណ៍ $A$៖ «ឃ្លីពណ៌ដូចគ្នាទាំងអស់» (ខៀវ ៣ ឬ ក្រហម ៣)៖\n$n(A) = C(4, 3) + C(5, 3) = 4 + 10 = 14$\n$P(A) = \\frac{14}{84} = \\frac{1}{6}$។\n\nខ. ព្រឹត្តិការណ៍ $B$៖ «ក្រហមយ៉ាងតិច ១»៖\nព្រឹត្តិការណ៍ផ្ទុយ $\\bar{B}$ គឺ «គ្មានក្រហមសោះ (ខៀវទាំង ៣)»៖\n$n(\\bar{B}) = C(4, 3) = 4 \\implies P(\\bar{B}) = \\frac{4}{84} = \\frac{1}{21}$\n$P(B) = 1 - P(\\bar{B}) = 1 - \\frac{1}{21} = \\frac{20}{21}$។",
        "officialSolutionEn": "Total C(9,3)=84. a. Same color: P = (C(4,3)+C(5,3))/84 = 14/84 = 1/6. b. At least 1 red: 1 - C(4,3)/84 = 20/21.",
