        "problemTextKm": "ក្នុងលំហប្រកបដោយតម្រុយអរតូណរម៉េ $(O, \\vec{i}, \\vec{j}, \\vec{k})$ គេឱ្យចំណុច $A(2, 0, 0)$, $B(0, 3, 0)$, $C(0, 0, 4)$ និង $D(1, 1, 1)$។\n\nក. គណនាផលគុណវ៉ិចទ័រ $\\vec{AB} \\times \\vec{AC}$។\n\nខ. សរសេរសមីការទូទៅនៃប្លង់ $(ABC)$។\n\nគ. គណនាចម្ងាយពីចំណុច $D$ មកកាន់ប្លង់ $(ABC)$។",
