        "officialSolutionKm": "ក. វ៉ិចទ័រ $\\vec{AB} = (-2, 3, 0)$ និង $\\vec{AC} = (-2, 0, 4)$៖\n$\\vec{n} = \\vec{AB} \\times \\vec{AC} = \\begin{vmatrix} \\vec{i} & \\vec{j} & \\vec{k} \\\\ -2 & 3 & 0 \\\\ -2 & 0 & 4 \\end{vmatrix} = 12\\vec{i} + 8\\vec{j} + 6\\vec{k} = (12, 8, 6)$ (ឬយក $\\vec{n}_0 = (6, 4, 3)$)។\n\nខ. សមីការប្លង់ $(ABC)$៖\nកាត់តាម $A(2, 0, 0)$ មានវ៉ិចទ័រណរម៉ាល់ $\\vec{n}_0 = (6, 4, 3)$៖\n$6(x - 2) + 4(y - 0) + 3(z - 0) = 0 \\implies 6x + 4y + 3z - 12 = 0$ (ឬសមីការជាកំណាត់ $\\frac{x}{2} + \\frac{y}{3} + \\frac{z}{4} = 1$)។\n\nគ. ចម្ងាយពី $D(1, 1, 1)$ មកប្លង់ $(ABC)$៖\n$d(D, (ABC)) = \\frac{|6(1) + 4(1) + 3(1) - 12|}{\\sqrt{6^2 + 4^2 + 3^2}} = \\frac{|13 - 12|}{\\sqrt{36 + 16 + 9}} = \\frac{1}{\\sqrt{61}} = \\frac{\\sqrt{61}}{61}$ ឯកតាប្រវែង។",
