        "titleEn": "Problem 1: DNA Molecular Calculations",
        "problemTextKm": "ម៉ូលេគុល ADN មួយមានប្រវែង $5100\\text{ \\AA}$ និងមាននុយក្លេអូទីតប្រភេទ អាដេនីន ($A$) ស្មើនឹង $20\\%$ នៃចំនួននុយក្លេអូទីតសរុប។\n\nក. គណនាចំនួននុយក្លេអូទីតសរុប ($N$) នៃម៉ូលេគុល ADN នេះ។\nខ. គណនាចំនួននុយក្លេអូទីតប្រភេទនីមួយៗ ($A, T, G, C$)។\nគ. គណនាចំនួនសម្ព័ន្ធអ៊ីដ្រូសែន ($H$) ដែលភ្ជាប់ច្រវាក់ទាំងពីរនៃម៉ូលេគុល ADN នេះ។",
        "problemTextEn": "A DNA molecule has length 5100 Angstroms and A = 20% of total nucleotides. Calculate total nucleotides N, count of each type, and hydrogen bonds.",
        "officialSolutionKm": "ក. ចំនួននុយក្លេអូទីតសរុប ($N$)៖\nតាមរូបមន្ត $L = \\frac{N}{2} \\times 3.4\\text{ \\AA}$ នាំឱ្យ៖\n$$N = \\frac{2L}{3.4} = \\frac{2 \\times 5100}{3.4} = 3000\\text{ នុយក្លេអូទីត}$$\n\nខ. ចំនួននុយក្លេអូទីតប្រភេទនីមួយៗ៖\n- $A = T = 20\\% \\times 3000 = 600\\text{ នុយក្លេអូទីត}$\n- តាមច្បាប់បំពេញបាស៖ $\\%G = 50\\% - \\%A = 50\\% - 20\\% = 30\\%$\n- $G = C = 30\\% \\times 3000 = 900\\text{ នុយក្លេអូទីត}$\n\nគ. ចំនួនសម្ព័ន្ធអ៊ីដ្រូសែន ($H$)៖\n$$H = 2A + 3G = 2(600) + 3(900) = 1200 + 2700 = 3900\\text{ សម្ព័ន្ធ}$$",
