        "titleEn": "Part 1: Reading Comprehension & Linguistics",
        "problemTextKm": "ចូរអានកថាខណ្ឌខាងក្រោម រួចឆ្លើយសំណួរ៖\n«ការរីកចម្រើននៃវិទ្យាសាស្ត្រ និងបច្ចេកវិទ្យាក្នុងយុគសម័យឌីជីថល បានផ្លាស់ប្តូរទម្លាប់រស់នៅរបស់មនុស្សជាតិយ៉ាងខ្លាំងក្លា។ ក៏ប៉ុន្តែ ការអភិវឌ្ឍនេះត្រូវតែដើរទន្ទឹមគ្នានឹងគុណធម៌ និងសីលធម៌ ទើបធានាបាននូវសន្តិភាព និងសុភមង្គលពិតប្រាកដ។»\n\nក. ស្រង់ពាក្យកម្ចីបាលី-សំស្ក្រឹតចំនួន ៤ ពាក្យពីក្នុងអត្ថបទខាងលើ។\nខ. ពន្យល់ន័យពាក្យ «គុណធម៌» និង «ឌីជីថល»។\nគ. យោងតាមអត្ថបទ តើអ្វីដែលត្រូវដើរទន្ទឹមគ្នានឹងការរីកចម្រើនបច្ចេកវិទ្យា? ហេតុអ្វី?",
        "problemTextEn": "Read the excerpt on STEM progress and ethics, extract 4 Pali-Sanskrit loanwords, explain key vocabulary, and explain why moral ethics must accompany technological advancement.",
        "officialSolutionKm": "ក. ពាក្យកម្ចីបាលី-សំស្ក្រឹត៖ វិទ្យាសាស្ត្រ, បច្ចេកវិទ្យា, យុគសម័យ, គុណធម៌, សីលធម៌, សន្តិភាព, សុភមង្គល។\nខ. ពន្យល់ពាក្យ៖\n- គុណធម៌ ៖ អំពើល្អ, សេចក្តីល្អបរិសុទ្ធក្នុងចិត្តដែលនាំឱ្យមនុស្សប្រព្រឹត្តត្រូវ។\n- ឌីជីថល ៖ បច្ចេកវិទ្យាអេឡិចត្រូនិកដែលដំណើរការដោយប្រព័ន្ធលេខកូដកុំព្យូទ័រ (០ និង ១)។\nគ. អ្វីដែលត្រូវដើរទន្ទឹមគ្នាគឺ «គុណធម៌ និងសីលធម៌» ព្រោះបើបច្ចេកវិទ្យាជឿនលឿនតែមនុស្សខ្វះសីលធម៌ នោះនឹងបង្កើតជាអាវុធបំផ្លិចបំផ្លាញ និងការកេងប្រវ័ញ្ចសង្គម។",
