        "titleEn": "Part 2: Philosophical Discussion Essay",
        "problemTextKm": "ប្រធាន ៖ មានមតិមួយពោលថា ៖ «ទ្រព្យសម្បត្តិជាកត្តាចម្បងបំផុតដែលនាំមកនូវសុភមង្គលក្នុងគ្រួសារ»។ ប៉ុន្តែមានមតិមួយទៀតយល់ថា ៖ «សេចក្តីស្រឡាញ់ និងការយោគយល់គ្នាទៅវិញទៅមក ទើបជាគ្រឹះពិតប្រាកដនៃសុភមង្គល»។\n\nចូរពិភាក្សាមតិទាំងពីរខាងលើនេះឱ្យបានក្បោះក្បាយ។",
        "problemTextEn": "Discuss the thesis: Material wealth is the primary source of family happiness vs the antithesis: Mutual love and empathy form the true foundation of happiness.",
        "officialSolutionKm": "គម្រោងតែងសេចក្តីបែបពិភាក្សា៖\n១. សេចក្តីផ្តើម៖ លំនាំបញ្ហាលើនិយមន័យសុភមង្គល លើកមតិទី១ និងមតិទី២ ចោទជាសំណួរពិភាក្សា។\n២. តួសេចក្តី៖\n- បកស្រាយមតិទី១៖ ទ្រព្យសម្បត្តិជាតម្រូវការរូបវន្តចាំបាច់ (ម្ហូបអាហារ ទីជម្រក ថ្លៃព្យាបាលជំងឺ ការសិក្សារបស់កូន)។ ខ្វះទ្រព្យអាចកើតជម្លោះក្នុងគ្រួសារ។\n- បកស្រាយមតិទី២៖ ទ្រព្យច្រើនតែខ្វះការយោគយល់ ក្បត់ចិត្តគ្នា ក៏គ្មានសុភមង្គលដែរ។ សេចក្តីស្រឡាញ់ ភាពស្មោះត្រង់ និងការអត់ឱនជាគ្រឿងផ្សះផ្សាផ្លូវចិត្ត។\n- សំយោគមតិ៖ កត្តាទាំងពីរត្រូវបំពេញឱ្យគ្នាទៅវិញទៅមក ដូចស្លាបសត្វទាំងសងខាង។\n៣. សេចក្តីបញ្ចប់៖ សន្និដ្ឋានរួម និងទស្សនៈផ្ទាល់ខ្លួន។",
