        "titleEn": "National Olympiad Essay: Cultural Identity and Modern Progress",
        "problemTextKm": "ប្រធាន ៖ មានទស្សនវិទូមួយរូបបានពោលថា ៖ «វប្បធម៌ និងអក្សរសិល្ប៍ជាតិ គឺជាព្រលឹង និងជាខែលការពារអត្តសញ្ញាណរបស់ជាតិមួយ។ ប្រទេសមួយអាចរីកចម្រើនខាងសម្ភារៈ តែបើបាត់បង់ព្រលឹងវប្បធម៌ នោះជាការអភិវឌ្ឍដែលគ្មាននិរន្តរភាពឡើយ»។\n\nចូរវិភាគ និងបកស្រាយទស្សនៈខាងលើឱ្យបានក្បោះក្បាយ ដោយលើកឧទាហរណ៍ក្នុងប្រវត្តិសាស្ត្រ និងស្នាដៃអក្សរសិល្ប៍ខ្មែរមកបញ្ជាក់។",
        "problemTextEn": "National Olympiad prompt analyzing culture and literature as the metaphysical soul and identity shield of a sovereign nation.",
        "officialSolutionKm": "គម្រោងតែងសេចក្តីកម្រិតជ័យលាភីសិស្សពូកែ៖\n១. សេចក្តីផ្តើម៖ បង្ហាញពីទំនាក់ទំនងស៊ីជម្រៅរវាងការអភិវឌ្ឍសម្ភារៈ និងអត្តសញ្ញាណវប្បធម៌ លើកប្រធាន និងចោទបញ្ហា។\n២. តួសេចក្តី៖\n- និយមន័យ «វប្បធម៌ និងអក្សរសិល្ប៍» និង «ការអភិវឌ្ឍគ្មាននិរន្តរភាព»។\n- ភស្តុតាងប្រវត្តិសាស្ត្រ៖ សម័យអង្គរ រុងរឿងព្រោះមានមូលដ្ឋានគ្រឹះស្មារតី ជំនឿ សាសនា និងសិល្បៈចម្លាក់រឹងមាំ។\n- អក្សរសិល្ប៍ជាកញ្ចក់ឆ្លុះសង្គម៖ ស្នាដៃលោក ញ៉ុក ថែម (កុលាបប៉ៃលិន), ក្រមង៉ុយ, រឿងរាមកេរ្តិ៍ បានអប់រំចិត្តគំនិតខ្មែរឱ្យស្គាល់តម្លៃសច្ចធម៌ និងសាមគ្គីភាព។\n- ការព្រមាន៖ បើទទួលយកតែស៊ីវិល័យបស្ចិមប្រទេសដោយភ្លេចឫសគល់ជាតិ នឹងធ្វើឱ្យសង្គមក្លាយជាសង្គមបាត់បង់អត្តសញ្ញាណ។\n៣. សេចក្តីបញ្ចប់៖ សំយោគទស្សនៈ ថែរក្សាអត្តសញ្ញាណជាតិ និងច្នៃប្រឌិតថ្មីក្នុងយុគឌីជីថល។",
