        "problemTextKm": "ក. ចូរពន្យល់ពីមូលហេតុដែលបណ្តាលឱ្យមានចលនាផ្លាស់ទីនៃប្លាកតិចតូនិចលើផ្ទៃផែនដី។\nខ. ហេតុអ្វីបានជាតំបន់ «ខ្សែក្រវាត់ភ្លើងប៉ាស៊ីហ្វិក» សម្បូរទៅដោយគ្រោះរញ្ជួយដី និងបន្ទុះភ្នំភ្លើងញឹកញាប់ជាងគេលើពិភពលោក?",
        "problemTextEn": "Explain mechanisms driving tectonic plate motion and analyze why the Pacific Ring of Fire experiences the highest seismic and volcanic activity.",
        "officialSolutionKm": "ក. មូលហេតុចលនាប្លាកតិចតូនិច៖ បណ្តាលមកពីចរន្តវិលវល់កម្តៅ (Convection Currents) នៅក្នុងស្រទាប់ម៉ង់តូផ្នែកខាងលើ (អាស្តេណូស្វ៊ែរ) ដែលរុញច្រានផ្ទាំងសំបកផែនដីឱ្យរំកិលបុកគ្នា ឬរំកិលចេញពីគ្នា។\nខ. ខ្សែក្រវាត់ភ្លើងប៉ាស៊ីហ្វិក៖ ជាតំបន់ព្រំប្រទល់ប្លាកតិចតូនិចជាច្រើនបុកទង្គិចគ្នា (Convergent Boundaries) និងការស្រុតចុះនៃសំបកមហាសមុទ្រចូលទៅក្នុងម៉ង់តូ បង្កើតជាសម្ពាធម៉ាក់ម៉ា និងការកកិតរញ្ជួយដីខ្លាំងក្លាជាប្រចាំ។",
