        "titleEn": "Problem 1: Applied Business Statistics",
        "problemTextKm": "តារាងខាងក្រោមបង្ហាញពីប្រាក់ចំណូលប្រចាំថ្ងៃ (គិតជាពាន់រៀល) របស់អាជីវកម្មខ្នាតតូចចំនួន ៤០ កន្លែង៖\n\n| ចន្លោះចំណូល ($x_i$) | ចំនួនអាជីវកម្ម ($f_i$) |\n|---|---|\n| [100, 200) | 8 |\n| [200, 300) | 14 |\n| [300, 400) | 12 |\n| [400, 500) | 6 |\n\nក. គណនាប្រាក់ចំណូលមធ្យមប្រចាំថ្ងៃ ($\\bar{x}$) នៃអាជីវកម្មទាំង ៤០។\nខ. កំណត់ថ្នាក់ម៉ូត និងគណនាម៉ូត ($M_o$) នៃទិន្នន័យខាងលើ។",
