        "problemTextEn": "Examine signatories and historical milestones of the October 23, 1991 Paris Peace Accords ending decades of civil conflict.",
        "officialSolutionKm": "ក. ភាគីចូលរួម៖\n- ភាគីជម្លោះកម្ពុជាទាំង ៤៖ រដ្ឋកម្ពុជា (SOC), ហ៊្វុនស៊ិនប៉ិច, រណសិរ្សរំដោះជាតិប្រជាពលរដ្ឋខ្មែរ (KPNLF), និងខ្មែរក្រហម (PDK)\n- ប្រទេសសហប្រធាន៖ បារាំង និងឥណ្ឌូនេស៊ី រួមជាមួយសមាជិកអចិន្ត្រៃយ៍ក្រុមប្រឹក្សាសន្តិសុខ UN ទាំង ៥ (P5)។\n\nខ. សារៈសំខាន់ជាប្រវត្តិសាស្ត្រ៖\n- បញ្ចប់ជាផ្លូវការនូវសង្គ្រាមស៊ីវិល និងការជ្រៀតជ្រែកពីបរទេស\n- បង្កើតបេសកកម្ម UNTAC រៀបចំការបោះឆ្នោតជាតិជាប្រវត្តិសាស្ត្រនៅខែឧសភា ឆ្នាំ១៩៩៣\n- បង្កើតរដ្ឋធម្មនុញ្ញថ្មី និងការប្រសូតឡើងវិញនៃ «ព្រះរាជាណាចក្រកម្ពុជាទី២» ក្រោមរបបរាជានិយមអាស្រ័យរដ្ឋធម្មនុញ្ញ។",
